import{_ as t,o as a,c as r,a2 as i}from"./chunks/framework.mRCPFc5l.js";const p=JSON.parse('{"title":"Gallery","description":"Display entries as cards with images.","frontmatter":{"title":"Gallery","description":"Display entries as cards with images."},"headers":[],"relativePath":"en/ansichten/galerie.md","filePath":"en/ansichten/galerie.md","lastUpdated":1787319236000}'),o={name:"en/ansichten/galerie.md"};function s(n,e,l,d,h,c){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="gallery" tabindex="-1">Gallery <a class="header-anchor" href="#gallery" aria-label="Permalink to &quot;Gallery&quot;">​</a></h1><p>The <strong>Gallery</strong> shows entries as cards — with an image, if you like.</p><p>The interface describes it as <em>An overview of your data</em>: <em>Display your data as gallery cards.</em></p><p><strong>Suited for:</strong> product catalogs, people directories, real estate, materials, portfolios — anything where the image matters more than the table row.</p><h2 id="create-a-gallery" tabindex="-1">Create a gallery <a class="header-anchor" href="#create-a-gallery" aria-label="Permalink to &quot;Create a gallery&quot;">​</a></h2><ol><li>Under the Grid, choose <strong>Create view</strong>.</li><li>Choose <strong>Gallery</strong>.</li></ol><p>Unlike Kanban, Calendar, and Map, the Gallery needs <strong>no special column</strong>. It works right away — it just looks better with images.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>Under <strong>Settings</strong>:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Choices</th><th>Effect</th></tr></thead><tbody><tr><td><strong>Image</strong></td><td><em>First image</em> / <em>No image</em></td><td>Whether and which image appears on the card</td></tr><tr><td><strong>Card size</strong></td><td><em>Small</em> / <em>Medium</em> / <em>Large</em></td><td>Card size, and thus how many fit per row</td></tr><tr><td><strong>Field icon</strong></td><td>on/off</td><td>Shows the column type&#39;s icon before each value</td></tr><tr><td><strong>Field name</strong></td><td>on/off</td><td>Shows the field name before each value</td></tr><tr><td><strong>URL fields as buttons</strong></td><td>on/off</td><td>Displays weblink fields as buttons</td></tr></tbody></table><h3 id="image" tabindex="-1">Image <a class="header-anchor" href="#image" aria-label="Permalink to &quot;Image&quot;">​</a></h3><p><strong>First image</strong> takes the first image from a column of type <strong>Files</strong>. If the entry has no image, the area stays empty.</p><p><strong>No image</strong> shows plain text cards — useful if there are no images but the card layout is still tidier than a table.</p><div class="tip custom-block"><p class="custom-block-title">Images belong up front</p><p>The gallery takes the <strong>first</strong> image of the files field. To control which one that is, sort the attachments within the entry accordingly — or create a dedicated &quot;Cover image&quot; column that holds only one image.</p></div><h3 id="card-size" tabindex="-1">Card size <a class="header-anchor" href="#card-size" aria-label="Permalink to &quot;Card size&quot;">​</a></h3><p><em>Small</em> shows many entries at a glance, <em>Large</em> puts the image front and center. <em>Medium</em> is the compromise.</p><div class="tip custom-block"><p class="custom-block-title">Choose the size based on use</p><p>For a <a href="/en/seiten/portal-veroeffentlichen">portal</a> showing customers a catalog, <em>Large</em> is usually right. For internal maintenance of many entries, <em>Small</em> is more practical.</p></div><h3 id="field-icon-and-field-name" tabindex="-1">Field icon and field name <a class="header-anchor" href="#field-icon-and-field-name" aria-label="Permalink to &quot;Field icon and field name&quot;">​</a></h3><p>Both toggles control how much extra detail appears per value. Turned off, the cards look tidier, but it&#39;s less clear which value belongs to what.</p><div class="tip custom-block"><p class="custom-block-title">Turn both off for portals</p><p>Internal field names like <code>status_2</code> or <code>net_price</code> are confusing for outsiders. Without field names and icons, a published gallery looks noticeably more professional.</p></div><h3 id="url-fields-as-buttons" tabindex="-1">URL fields as buttons <a class="header-anchor" href="#url-fields-as-buttons" aria-label="Permalink to &quot;URL fields as buttons&quot;">​</a></h3><p>Turns fields of type <strong>Weblink</strong> into buttons instead of plain text — handy for &quot;Go to shop,&quot; &quot;Data sheet,&quot; &quot;Learn more.&quot;</p><h2 id="which-fields-appear-on-the-card" tabindex="-1">Which fields appear on the card <a class="header-anchor" href="#which-fields-appear-on-the-card" aria-label="Permalink to &quot;Which fields appear on the card&quot;">​</a></h2><p>As with every view, this is controlled via the visible columns. Hidden columns don&#39;t appear on the card.</p><p>→ <a href="/en/ansichten/spalten-verwalten">Manage columns</a></p><div class="tip custom-block"><p class="custom-block-title">Fewer fields, better cards</p><p>A gallery card with fifteen fields isn&#39;t a gallery anymore, it&#39;s a narrow table. Hide everything that isn&#39;t needed at a glance.</p></div><h2 id="filter-and-sort" tabindex="-1">Filter and sort <a class="header-anchor" href="#filter-and-sort" aria-label="Permalink to &quot;Filter and sort&quot;">​</a></h2><p>Work as in any view. Sorting determines the order of the cards.</p><p>→ <a href="/en/ansichten/filtern-sortieren-gruppieren">Filtering, Sorting, Grouping</a></p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/ansichten/was-ist-eine-ansicht">What is a View</a></li><li><a href="/en/ansichten/spalten-verwalten">Manage columns</a></li><li><a href="/en/seiten/portal-veroeffentlichen">Publishing a portal</a></li></ul>',31)])])}const g=t(o,[["render",s]]);export{p as __pageData,g as default};
